using Nafadh_Backend.Enums;
using Nafadh_Backend.Models;
using Nafadh_Backend.Repositories;
using static Nafadh_Backend.DTOs.ExcuseDto;

namespace Nafadh_Backend.Services
{
    public class ExcuseService : IExcuseService
    {
        private readonly IExcuseRepository _repository;

        public ExcuseService(IExcuseRepository repository)
        {
            _repository = repository;
        }
        public async Task<ExcuseReadDto?> GetByDailyAttendanceIdAsync(
           int dailyAttendanceId)
        {
            NFD_Excuse? entity =
                await _repository.GetByDailyAttendanceIdAsync(
                    dailyAttendanceId);

            if (entity == null)
                return null;

            return MapToReadDto(entity);
        }

        public async Task<ExcuseReadDto> CreateAsync(
            CreateExcuseDto dto)
        {
            // لا يسمح بأكثر من عذر لنفس سجل الغياب
            NFD_Excuse? existing =
                await _repository.GetByDailyAttendanceIdAsync(
                    dto.DailyAttendanceId);

            if (existing != null)
            {
                throw new InvalidOperationException(
                    "An excuse already exists for this attendance record.");
            }

            NFD_Excuse entity = new NFD_Excuse
            {
                Reason = dto.Reason,
                ProofUrl = dto.ProofUrl,
                DailyAttendanceId = dto.DailyAttendanceId,

                // أي عذر جديد يكون Pending
                // وبالتالي يظهر عند المدرب
                Status = NFD_ExcuseStatus.Pending
            };

            NFD_Excuse created =
                await _repository.AddAsync(entity);

            return MapToReadDto(created);
        }

        public async Task<bool> ReviewAsync(int id, ReviewExcuseDto dto)
        {
            NFD_Excuse? entity = await _repository.GetByIdAsync(id);

            if (entity == null)
                return false;

            // لا يمكن مراجعة العذر أكثر من مرة
            if (entity.Status != NFD_ExcuseStatus.Pending)
                throw new InvalidOperationException(
                    "This excuse has already been reviewed.");

            // التأكد أن سجل الحضور المرتبط بالعذر موجود
            if (entity.DailyAttendance == null)
                throw new InvalidOperationException(
                    "The attendance record linked to this excuse was not found.");

            if (dto.IsApproved)
            {
                // قبول العذر
                entity.Status = NFD_ExcuseStatus.Approved;

                // تحويل الغياب إلى غياب بعذر
                entity.DailyAttendance.Status =
                    NFD_AttendanceStatus.Excused;
            }
            else
            {
                // رفض العذر
                entity.Status = NFD_ExcuseStatus.Rejected;

                // يبقى غياب بدون عذر
                entity.DailyAttendance.Status =
                    NFD_AttendanceStatus.Absent;
            }

            // حفظ الشخص الذي راجع العذر
            entity.ReviewedByUserId = dto.ReviewedByUserId;

            await _repository.UpdateAsync(entity);

            return true;
        }

        public async Task<List<ExcuseReadDto>> GetPendingAsync()
        {
            List<NFD_Excuse> entities =
                await _repository.GetPendingAsync();

            List<ExcuseReadDto> result =
                new List<ExcuseReadDto>();

            foreach (NFD_Excuse entity in entities)
            {
                result.Add(MapToReadDto(entity));
            }

            return result;
        }


        // دالة مساعدة خاصة لتحويل الـ Entity إلى Dto
        private ExcuseReadDto MapToReadDto(
            NFD_Excuse entity)
        {
            return new ExcuseReadDto
            {
                ExcuseId = entity.ExcuseId,
                Reason = entity.Reason,
                ProofUrl = entity.ProofUrl,
                Status = entity.Status,
                DailyAttendanceId =
                    entity.DailyAttendanceId,
                ReviewedByUserId =
                    entity.ReviewedByUserId
            };
        }
    }
}